/**
 * AX-02: every workspace package and top-level directory has a README in its variant's shape.
 *
 * - published (a package whose package.json is not private, or an SDK under sdks/): install, quick
 *   start, what to do first, docs, agents, versions, license. Under 400 lines.
 * - internal (a private package, or a top-level directory read in the repo): where it sits, layout,
 *   work on it (generated by `pnpm gen readme-work`), rules, docs. Under 150 lines.
 * - action (actions/publish): permissions, a minimal workflow pinned by commit SHA, inputs.
 *
 * A directory that does not exist yet (`evals/`, `packages/agent-kit`) is skipped, so the test
 * covers it from the day it lands. A README that predates its variant and belongs to a later
 * package sits in TEMPLATE_DEBT with its owner; the ledger only shrinks: an entry that now
 * conforms fails the test until it is removed.
 */

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { parse } from "yaml";
import { applyBlock, TARGETS } from "./gen-readme-work.js";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

type Variant = "published" | "internal" | "action";

const HEADINGS: Record<Variant, string[]> = {
  published: [
    "Install",
    "Quick start",
    "Before you start",
    "Docs",
    "For agents",
    "Versions",
    "License",
  ],
  internal: ["Where it sits", "Layout", "Work on it", "Rules here", "Docs"],
  action: [
    "Permissions",
    "Minimal workflow",
    "Inputs",
    "What it does not do",
    "Docs",
    "Versions",
    "License",
  ],
};

const MAX_LINES: Record<Variant, number> = {
  published: 400,
  internal: 150,
  action: 150,
};

/** READMEs whose heading shape belongs to a later package. Each entry names it. */
const TEMPLATE_DEBT: Record<string, string> = {
  "packages/sdk-node": "SP-37: the SDK READMEs move to the published template",
  "packages/sdk-react": "SP-37: the SDK READMEs move to the published template",
  "sdks/python": "SP-37: the SDK READMEs move to the published template",
  "sdks/swift": "SP-37: the SDK READMEs move to the published template",
  "sdks/kotlin": "SP-37: the SDK READMEs move to the published template",
  "sdks/godot": "SP-37: the SDK READMEs move to the published template",
  "packages/cli":
    "AX-16: the CLI README takes the template with `--json` and `pkey explain`",
  "packages/client-core":
    "SP-37: the client-core README is reorganized with the SDK pages",
  "packages/brand":
    "AX-01 changes brand's metadata only; the README keeps its own shape",
};

interface Entry {
  dir: string;
  variant: Variant;
  /** The npm name the README's title must start with, for a package. */
  name?: string;
}

interface Manifest {
  name: string;
  private?: boolean;
}

function entries(): Entry[] {
  const out: Entry[] = [];
  for (const d of readdirSync(join(ROOT, "packages"), {
    withFileTypes: true,
  })) {
    const dir = `packages/${d.name}`;
    if (!d.isDirectory() || !existsSync(join(ROOT, dir, "package.json")))
      continue;
    // The manifest is this repository's own file, read for two fields.
    const pkg: Manifest = JSON.parse(
      readFileSync(join(ROOT, dir, "package.json"), "utf8"),
    );
    out.push({
      dir,
      variant: pkg.private === true ? "internal" : "published",
      name: pkg.name,
    });
  }
  for (const d of readdirSync(join(ROOT, "sdks"), { withFileTypes: true }))
    if (d.isDirectory())
      out.push({ dir: `sdks/${d.name}`, variant: "published" });
  for (const dir of ["conformance", "tools", "products", "docs", "evals"])
    if (existsSync(join(ROOT, dir))) out.push({ dir, variant: "internal" });
  out.push({ dir: "actions/publish", variant: "action" });
  return out;
}

/** The README's `# ` title and the `## ` headings outside code fences, in order. */
function outline(text: string): { title: string | undefined; h2: string[] } {
  let fence = false;
  let title: string | undefined;
  const h2: string[] = [];
  for (const line of text.split("\n")) {
    if (/^(```|~~~)/.test(line)) fence = !fence;
    if (fence) continue;
    if (title === undefined && line.startsWith("# "))
      title = line.slice(2).trim();
    else if (line.startsWith("## ")) h2.push(line.slice(3).trim());
  }
  return { title, h2 };
}

/** The wanted headings appear in order (other sections may sit between them). */
const inOrder = (want: string[], have: string[]): boolean => {
  let at = 0;
  for (const h of have) if (h === want[at]) at++;
  return at === want.length;
};

/** Problems with one README against its variant; empty when it conforms. */
function problems(entry: Entry): string[] {
  const text = readFileSync(join(ROOT, entry.dir, "README.md"), "utf8");
  const { title, h2 } = outline(text);
  const found: string[] = [];
  if (title === undefined) found.push("no `# ` title");
  else if (entry.name !== undefined && !title.startsWith(entry.name))
    found.push(`title "${title}" does not start with ${entry.name}`);
  if (!inOrder(HEADINGS[entry.variant], h2))
    found.push(
      `headings must include, in order: ${HEADINGS[entry.variant].join(", ")}; found: ${h2.join(", ")}`,
    );
  const lines = text.split("\n").length;
  if (lines > MAX_LINES[entry.variant])
    found.push(`${lines} lines, over the ${MAX_LINES[entry.variant]} line cap`);
  return found;
}

describe("README coverage", () => {
  const all = entries();

  it("finds the directories to cover", () => {
    const dirs = all.map((e) => e.dir);
    expect(dirs).toEqual(
      expect.arrayContaining([
        "packages/worker",
        "packages/shared-jws",
        "sdks/python",
        "conformance",
        "actions/publish",
      ]),
    );
  });

  it("has no debt entry for a directory that is not covered", () => {
    const dirs = all.map((e) => e.dir);
    for (const dir of Object.keys(TEMPLATE_DEBT))
      expect(dirs, dir).toContain(dir);
  });

  for (const entry of all)
    describe(entry.dir, () => {
      it("has a README", () => {
        expect(existsSync(join(ROOT, entry.dir, "README.md"))).toBe(true);
      });

      const debt = TEMPLATE_DEBT[entry.dir];
      if (debt !== undefined)
        it(`still owes its ${entry.variant} shape (${debt})`, () => {
          expect(
            problems(entry),
            "conforms now: remove it from TEMPLATE_DEBT",
          ).not.toEqual([]);
        });
      else
        it(`is in the ${entry.variant} shape`, () => {
          expect(problems(entry)).toEqual([]);
        });
    });
});

describe("internal READMEs", () => {
  const targets = TARGETS.map((t) => t.dir);

  for (const entry of entries().filter((e) => e.variant === "internal"))
    it(`${entry.dir} has a work-on-it generator target and its markers`, () => {
      // A new internal directory adds a TARGETS row in tools/gen-readme-work.ts.
      expect(targets).toContain(entry.dir);
      const text = readFileSync(join(ROOT, entry.dir, "README.md"), "utf8");
      // applyBlock throws when the markers are missing.
      expect(() =>
        applyBlock(text, "", `${entry.dir}/README.md`),
      ).not.toThrow();
    });
});

describe("conformance runners", () => {
  // Private workspace packages whose README points at conformance/README.md.
  for (const name of ["node", "browser"])
    it(`conformance/runners/${name} has a README that points at conformance/README.md`, () => {
      const dir = `conformance/runners/${name}`;
      const text = readFileSync(join(ROOT, dir, "README.md"), "utf8");
      const pkg: Manifest = JSON.parse(
        readFileSync(join(ROOT, dir, "package.json"), "utf8"),
      );
      expect(text.split("\n")[0]).toBe(`# ${pkg.name}`);
      expect(text).toContain("](../../README.md)");
    });
});

describe("packages/client-core/README.md", () => {
  it("lists every package.json subpath export in its table", () => {
    const pkg = JSON.parse(
      readFileSync(join(ROOT, "packages/client-core/package.json"), "utf8"),
    ) as { name: string; exports: Record<string, unknown> };
    const text = readFileSync(
      join(ROOT, "packages/client-core/README.md"),
      "utf8",
    );
    for (const key of Object.keys(pkg.exports)) {
      const specifier = key === "." ? pkg.name : `${pkg.name}/${key.slice(2)}`;
      expect(text, specifier).toContain(`| \`${specifier}\``);
    }
  });
});

describe("actions/publish/README.md", () => {
  const text = readFileSync(
    join(ROOT, "actions", "publish", "README.md"),
    "utf8",
  );

  it("pins the Action by commit SHA with a version comment", () => {
    expect(text).toMatch(
      /uses: vladzaharia\/polaris-key\/actions\/publish@[0-9a-f]{40} # v\d+\.\d+\.\d+/,
    );
    expect(text).not.toMatch(/actions\/publish@(v\d|main|master)/);
  });

  it("asks for the OIDC permission", () => {
    expect(text).toContain("id-token: write");
  });

  it("links the generated Action reference", () => {
    expect(text).toContain("https://key.plrs.im/docs/reference/github-action/");
  });
});

interface WorkflowJob {
  needs?: string;
  steps?: { uses?: string; with?: Record<string, string> }[];
}

function minimalWorkflow(text: string): { jobs: Record<string, WorkflowJob> } {
  const match = text.match(/## Minimal workflow\n\n```yaml\n([\s\S]*?)\n```/);
  expect(match).not.toBeNull();
  return parse(match?.[1] ?? "") as { jobs: Record<string, WorkflowJob> };
}

function workflowJob(text: string, name: string): WorkflowJob {
  const job = minimalWorkflow(text).jobs[name];
  if (!job) throw new Error(`missing ${name} job`);
  return job;
}

describe("actions/publish/README.md workflow", () => {
  const text = readFileSync(
    join(ROOT, "actions", "publish", "README.md"),
    "utf8",
  );

  it("carries a named build artifact into the publishing job", () => {
    const build = workflowJob(text, "build");
    const publish = workflowJob(text, "publish");
    expect(build.steps).toContainEqual(
      expect.objectContaining({
        uses: "actions/upload-artifact@v4",
        with: expect.objectContaining({
          name: "release-files",
          path: "dist",
          "if-no-files-found": "error",
        }),
      }),
    );
    expect(publish.needs).toBe("build");
    expect(publish.steps).toContainEqual(
      expect.objectContaining({
        uses: "actions/download-artifact@v4",
        with: expect.objectContaining({
          name: "release-files",
          path: "dist",
        }),
      }),
    );
  });

  it("uses the publish Action's release inputs", () => {
    const steps = workflowJob(text, "publish").steps;
    expect(steps).toContainEqual(
      expect.objectContaining({
        uses: "vladzaharia/polaris-key/actions/publish@d49e25a51ecc70e0335075a970b2d35868ec2e38",
        with: expect.objectContaining({
          product: "your-product",
          tag: "${{ github.ref_name }}",
          channel: "beta",
          dir: "dist",
          "release-key": "${{ secrets.PKEY_RELEASE_KEY }}",
        }),
      }),
    );
  });
});
